'use strict';
const $ = (s, root = document) => root.querySelector(s);
const app = $('#app'), modal = $('#modal');
const memoryStorage=new Map();let storageUnavailable=false;
function saved(key){try{return sessionStorage.getItem(key)}catch{storageUnavailable=true;return memoryStorage.get(key)||''}}
function remember(key,value){memoryStorage.set(key,value);try{sessionStorage.setItem(key,value)}catch{toast('브라우저 저장소를 사용할 수 없어 현재 화면에서만 역할을 유지합니다',true)}}
let operatorMode=saved('ax-operator-mode')||'admin', operatorEntity=saved('ax-operator-entity')||'', operatorCatalogue=[];
let state, route = {page:'dashboard'}, filters={search:'',stage:'',industry:'',serviceType:'',view:'board'}, taskFilter='open', comparisonId='', busy=false;
const stages={consultation:'상담',quotation:'견적',progress:'진행',completed:'완료'};
const milestoneStatus={planned:'준비 중',submitted:'검수 대기',revision:'수정 요청',approved:'검수 완료'};
const serviceTypes={ax:'AX 구축',education:'AI 교육',infrastructure:'AI 인프라'};
const accents={consultation:'#9aacb3',quotation:'#dca573',progress:'#8daacb',completed:'#a9bf89'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ko-KR').format(Number(n)||0);
const won=n=>Number(n)>=10000?`${money(Number(n)/10000)}<small>만원</small>`:`${money(n)}<small>원</small>`;
const date=v=>v?esc(v.replaceAll('-','.')):'미정';
const shortDate=v=>v?esc(v.slice(5).replace('-','.')):'일정 미정';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dd=v=>Math.round((new Date(v+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000);
const due=v=>!v?'':dd(v)<0?`<span class="due late">${Math.abs(dd(v))}일 지남</span>`:dd(v)===0?'<span class="due">오늘</span>':dd(v)<=3?`<span class="due">D-${dd(v)}</span>`:'';
const iconPaths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',compare:'<rect x="3" y="4" width="7" height="16" rx="1.5"/><rect x="14" y="4" width="7" height="16" rx="1.5"/><path d="M6 8h1m10 0h1M6 12h1m10 0h1M6 16h1m10 0h1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-15a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',check:'<path d="m5 12 4 4L19 6"/>',checklist:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m7 8 1 1 2-2m3 1h4M7 13h3m3 0h4M7 17h3m3 0h4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 6 6 6-6 6"/>',back:'<path d="m14 6-6 6 6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',trend:'<path d="m3 17 6-6 4 4 8-10m-6 0h6v6"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18m-6 4h6v4h-6z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m15 4 5 5M4 20l1-6L16 3a2 2 0 0 1 3 0l2 2a2 2 0 0 1 0 3L10 19z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',book:'<path d="M12 6C9 3 5 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2zm0 0v15"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',building:'<rect x="5" y="3" width="14" height="18" rx="1"/><path d="M9 7h1m4 0h1m-6 4h1m4 0h1m-6 4h1m4 0h1m-4 6v-3h2v3"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.folder}</svg>`;
const badge=(s,labels=stages)=>`<span class="badge ${esc(s)}">${esc(labels[s]||s)}</span>`;
const demo=p=>p.isDemo?'<span class="badge demo">가상</span>':'';
const supplier=id=>state.suppliers.find(s=>s.id===id);
const project=id=>state.projects.find(p=>p.id===id);
const quotesFor=id=>state.quotes.filter(q=>q.projectId===id);
const milestonesFor=id=>state.milestones.filter(m=>m.projectId===id);
const tasksFor=id=>state.tasks.filter(t=>t.projectId===id);
const companyIcon=p=>`<span class="company-icon ${p.industry==='제조업'?'blue':p.serviceType==='education'?'orange':''}">${esc(p.company.replace('가상 ','').slice(0,2))}</span>`;
const btn=(action,label,kind='',i='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${i?icon(i):''}${label}</button>`;
const iconBtn=(action,label,i,extra='')=>`<button type="button" class="icon-btn" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra}>${icon(i)}</button>`;
const empty=(title,sub,action='')=>`<div class="empty">${icon('folder')}<h3>${title}</h3><p>${sub}</p>${action}</div>`;
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500)}
async function api(path,method='GET',data){const res=await fetch(`/api/${path}`,{method,headers:{...(data!==undefined?{'Content-Type':'application/json'}:{}),'X-Demo-Role':operatorMode,'X-Demo-Entity':operatorEntity},body:data!==undefined?JSON.stringify(data):undefined});let result;try{result=await res.json()}catch{throw Error('서버 응답을 읽지 못했습니다. 실행 상태를 확인해 주세요.')}if(!res.ok)throw Error(result.error||'요청을 처리하지 못했습니다.');return result}
let refreshVersion=0;
async function refresh(){const sequence=++refreshVersion,mode=operatorMode,entity=operatorEntity;try{const next=await api('state');if(sequence!==refreshVersion||mode!==operatorMode||entity!==operatorEntity)return false;state=next;if(operatorMode==='admin'||!operatorCatalogue.length)operatorCatalogue=state.salespeople||[];render();if(storageUnavailable){toast('브라우저 저장소가 차단되어 현재 화면에서만 역할을 유지합니다',true);storageUnavailable=false}return true}catch(error){if(sequence!==refreshVersion)return false;throw error}}
function parseRoute(){const parts=location.hash.slice(1).split('/');return {page:parts[0]||'dashboard',id:parts[1]||'',tab:parts[2]||'overview'}}
function pageLabel(){return {dashboard:'대시보드',projects:'프로젝트',compare:'견적 비교',suppliers:'공급사',tasks:'다음 할 일',settings:'데이터 관리',programs:'지원사업',investments:'투자 검토',crm:'영업 CRM'}[route.page]||'대시보드'}
function render(){route=parseRoute();if(!state)return;app.innerHTML=`<div class="shell"><aside class="sidebar"><a href="/" class="brand" aria-label="AX브릿지 홈"><span class="brandmark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 20V9m18 11V9M3 15h18M3 9c5 0 5-5 9-5s4 5 9 5M8 12v8m8-8v8"/></svg></span>AX브릿지</a><div class="workspace">OPERATIONS WORKSPACE</div><nav class="nav" aria-label="주요 메뉴">${[['dashboard','grid','대시보드'],['projects','folder','프로젝트'],['compare','compare','견적 비교'],['suppliers','users','공급사'],['crm','users','영업 CRM'],['programs','book','지원사업'],['investments','trend','투자 검토'],['tasks','checklist','다음 할 일'],['settings','settings','데이터 관리']].filter(([r])=>operatorMode==='admin'||!['programs','investments','settings','suppliers'].includes(r)).map(([r,i,l])=>`<a href="#${r}" class="${route.page===r?'active':''}">${icon(i)}${l}${r==='projects'?`<span class="count">${state.projects.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-card"><strong>작은 연결, 더 나은 전환</strong><span>AX 구축 · 교육 · AI 인프라까지<br>중개 업무를 한곳에서 관리하세요</span></div><div class="operator"><span class="avatar">AX</span><div><strong>내 운영 워크스페이스</strong><small>${operatorMode==='sales'?'담당 건만 표시 · 검토 모드':'전체 관리자 · 검토 모드'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">워크스페이스 ${icon('chevron')} <strong>${pageLabel()}</strong></div><div class="topright"><select id="operator-role" class="operator-role" aria-label="관리자 영업직원 시연 역할"><option value="admin">관리자 · 시연</option>${operatorCatalogue.map(s=>`<option value="sales:${s.id}" ${operatorMode==='sales'&&operatorEntity===s.id?'selected':''}>영업 · ${esc(s.name)}</option>`).join('')}</select><div class="role-links"><a href="/buyer.html">수요기업</a><a href="/supplier.html">공급기업</a><a href="/signup.html">검토용 가입</a></div><span class="top-date">${new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'})}</span><a href="#settings" class="local-status"><i></i>로컬 저장 · 로그인 미설정</a></div></header><div class="content">${renderPage()}<footer class="footer"><span>AX브릿지 · 내부 중개 운영실</span><span>검토용 MVP / 실제 고객·견적을 입력하기 전 인증 및 접근제어가 필요합니다</span></footer></div></main></div>`}
function renderPage(){if(operatorMode==='sales'&&['programs','investments','settings','suppliers'].includes(route.page))return empty('관리자 전용 메뉴입니다','영업직원 검토 모드에서는 담당 프로젝트만 열람할 수 있습니다');if(route.page==='projects'&&route.id)return renderProject();return ({dashboard:renderDashboard,projects:renderProjects,compare:renderCompare,suppliers:renderSuppliers,tasks:renderTasks,settings:renderSettings,programs:renderPrograms,investments:renderInvestments,crm:renderCRM}[route.page]||renderDashboard)()}
function pageHead(eyebrow,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function renderDashboard(){const active=state.projects.filter(p=>p.stage!=='completed'),late=state.tasks.filter(t=>!t.done&&t.dueDate&&dd(t.dueDate)<0),openTasks=state.tasks.filter(t=>!t.done).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));const received=state.quotes.filter(q=>q.status==='received');const review=state.milestones.filter(m=>m.status==='submitted');const priority=[...active].sort((a,b)=>({high:0,medium:1,low:2}[a.priority]-{high:0,medium:1,low:2}[b.priority]));const comparison=state.projects.filter(p=>p.stage==='quotation').slice(0,2);
return `${pageHead('YOUR WORK, CONNECTED','오늘의 운영 현황','놓치지 말아야 할 다음 단계부터 확인해 보세요',btn('new-project','프로젝트 등록','primary','plus'))}<div class="stats"><div class="stat top"><div class="stat-title">진행 중인 기회 ${icon('folder')}</div><div class="stat-number">${active.length}<small>건</small></div><div class="stat-note">구축 ${active.filter(p=>p.serviceType==='ax').length} · 교육 ${active.filter(p=>p.serviceType==='education').length} · 인프라 ${active.filter(p=>p.serviceType==='infrastructure').length}</div></div><div class="stat"><div class="stat-title">활성 프로젝트 예산 ${icon('wallet')}</div><div class="stat-number">${won(active.reduce((s,p)=>s+p.budget,0))}</div><div class="stat-note">고객 희망 예산 합계 · 매출 아님</div></div><div class="stat"><div class="stat-title">접수된 견적 ${icon('compare')}</div><div class="stat-number">${received.length}<small>건</small></div><div class="stat-note">${state.projects.filter(p=>p.stage==='quotation').length}개 프로젝트 비교 진행 중</div></div><div class="stat"><div class="stat-title">검수가 필요한 결과물 ${icon('checklist')}</div><div class="stat-number">${review.length}<small>건</small></div><div class="stat-note ${late.length?'alert':''}">${late.length?`기한이 지난 할 일 ${late.length}건도 확인하세요`:'예정된 검수 일정을 확인하세요'}</div></div></div><div class="dashboard-grid"><section class="pipeline-panel"><div class="section-title"><h2>프로젝트 파이프라인</h2><a href="#projects">전체 보기 ${icon('chevron')}</a></div><div class="pipeline-summary">${Object.entries(stages).map(([s,l])=>`<a href="#projects" data-stage-filter="${s}" class="pipeline-item" style="--accent:${accents[s]}"><span><i class="dot"></i>${l}</span><b>${state.projects.filter(p=>p.stage===s).length}</b></a>`).join('')}</div><div class="section-title"><p>지금 주목할 프로젝트</p><p>희망 완료일</p></div><div class="project-rows">${priority.slice(0,4).map(p=>`<a href="#projects/${p.id}" class="project-row">${companyIcon(p)}<div><span class="row-name">${esc(p.name)}</span><span class="row-sub">${esc(p.company)} · ${serviceTypes[p.serviceType]||'AX 구축'}</span></div>${badge(p.stage)}<span class="row-date">${shortDate(p.targetDate)}</span></a>`).join('')||empty('등록된 프로젝트가 없습니다','첫 상담을 등록해 보세요')}</div><div class="demo-notice">${icon('info')}샘플 고객과 프로젝트·견적은 실제 거래가 아닌 가상 데이터입니다</div></section><section class="todo-panel"><div class="section-title"><h2>다음 할 일</h2><span class="task-count">${openTasks.length}</span></div><div class="todo-list">${openTasks.slice(0,4).map(t=>taskRow(t,false)).join('')||'<p class="notice-small">남아 있는 할 일이 없습니다</p>'}</div><button type="button" class="link-btn" data-action="new-task">${icon('plus')}할 일 추가</button></section></div><section class="spotlight"><div><div class="spotlight-label">NEXT OPPORTUNITY</div><h3>비교할수록, 연결은 명확하게</h3><p>금액뿐 아니라 범위와 운영 조건까지 살펴보세요</p></div><div class="spotlight-projects">${comparison.map(p=>`<a href="#compare/${p.id}" class="spotlight-card"><div><strong>${esc(p.company)}</strong><span>${serviceTypes[p.serviceType]} · 견적 ${quotesFor(p.id).length}건 비교</span></div>${icon('chevron')}</a>`).join('')||'<p>현재 비교 대기 중인 프로젝트가 없습니다</p>'}</div></section>`}
function filteredProjects(){const q=filters.search.toLowerCase();return state.projects.filter(p=>(!q||`${p.name} ${p.company} ${p.contactName}`.toLowerCase().includes(q))&&(!filters.stage||p.stage===filters.stage)&&(!filters.industry||p.industry===filters.industry)&&(!filters.serviceType||p.serviceType===filters.serviceType))}
function projectCard(p){return `<a href="#projects/${p.id}" class="project-card"><div class="card-top"><span class="industry">${esc(p.industry||'업종 미정')} · ${serviceTypes[p.serviceType]||'AX 구축'}</span>${badge(p.priority,{high:'높음',medium:'보통',low:'낮음'})}</div><div class="card-company">${esc(p.company)}${demo(p)}</div><h3>${esc(p.name)}</h3><div class="card-money">${won(p.budget)}</div><div class="card-bottom"><span>${icon('calendar')}${shortDate(p.targetDate)}</span><span>${icon('compare')}${quotesFor(p.id).length}건</span></div></a>`}
function renderProjects(){const list=filteredProjects(),industries=[...new Set(state.projects.map(p=>p.industry).filter(Boolean))];return `${pageHead('PROJECT PIPELINE','프로젝트','상담에서 완료까지, 모든 연결을 놓치지 않도록',btn('new-project','프로젝트 등록','primary','plus'))}<div class="toolbar"><div class="filters"><label class="search">${icon('search')}<input id="project-search" class="filter" placeholder="고객사, 프로젝트, 담당자 검색" aria-label="프로젝트 검색" value="${esc(filters.search)}"></label><select id="service-filter" class="filter" aria-label="서비스 유형"><option value="">모든 서비스</option>${options(serviceTypes,filters.serviceType)}</select><select id="stage-filter" class="filter" aria-label="프로젝트 단계"><option value="">모든 단계</option>${options(stages,filters.stage)}</select><select id="industry-filter" class="filter" aria-label="업종"><option value="">모든 업종</option>${industries.map(i=>`<option ${i===filters.industry?'selected':''}>${esc(i)}</option>`).join('')}</select></div><div class="segmented" aria-label="보기 방식"><button type="button" data-action="view-board" class="${filters.view==='board'?'active':''}">보드</button><button type="button" data-action="view-list" class="${filters.view==='list'?'active':''}">목록</button></div></div><div id="project-results">${projectResults(list)}</div><p class="notice-small">가상으로 표시된 프로젝트는 시연용입니다. 공급사 확정 및 프로젝트 완료는 상세 화면에서 관리합니다</p>`}
function projectResults(list){if(filters.view==='list')return list.length?`<div class="table-wrap"><table><thead><tr><th>프로젝트 / 고객사</th><th>서비스</th><th>단계</th><th>예산</th><th>희망 완료일</th><th>담당자</th></tr></thead><tbody>${list.map(p=>`<tr><td><a href="#projects/${p.id}">${esc(p.name)}</a>${demo(p)}<div class="row-sub">${esc(p.company)}</div></td><td>${serviceTypes[p.serviceType]||'AX 구축'}</td><td>${badge(p.stage)}</td><td>${money(p.budget)}원</td><td>${date(p.targetDate)}</td><td>${esc(p.contactName||'미정')}</td></tr>`).join('')}</tbody></table></div>`:empty('검색 결과가 없습니다','검색어 또는 필터를 바꿔 보세요');return `<div class="kanban">${Object.entries(stages).filter(([s])=>!filters.stage||filters.stage===s).map(([s,l])=>`<section class="kanban-col"><div class="kanban-head"><strong><i class="dot" style="--accent:${accents[s]}"></i>${l}</strong><span>${list.filter(p=>p.stage===s).length}건</span></div>${list.filter(p=>p.stage===s).map(projectCard).join('')||'<div class="empty-col">아직 프로젝트가 없습니다</div>'}</section>`).join('')}</div>`}
function renderProject(){const p=project(route.id);if(!p)return empty('프로젝트를 찾을 수 없습니다','삭제되었거나 주소가 변경되었을 수 있습니다','<a href="#projects" class="btn">프로젝트 목록</a>');const q=quotesFor(p.id),m=milestonesFor(p.id);return `<a href="#projects" class="back">${icon('back')}프로젝트 목록</a><div class="page-head detail-head"><div><div class="eyebrow">${serviceTypes[p.serviceType]||'AX 구축'} · ${esc(p.industry||'업종 미정')}</div><div class="detail-title"><h1>${esc(p.name)}</h1>${badge(p.stage)}${demo(p)}</div><p>${esc(p.company)} · 담당 ${esc(p.contactName||'미정')}</p></div><div class="head-actions">${btn('edit-project','정보 수정','','edit',`data-id="${p.id}"`)}${iconBtn('delete-project','프로젝트 삭제','trash',`data-id="${p.id}"`)}</div></div><nav class="tabs" aria-label="프로젝트 상세"><a href="#projects/${p.id}/overview" class="${route.tab==='overview'?'active':''}">프로젝트 정보</a><a href="#projects/${p.id}/quotes" class="${route.tab==='quotes'?'active':''}">견적 비교<span class="tab-count">${q.length}</span></a><a href="#projects/${p.id}/milestones" class="${route.tab==='milestones'?'active':''}">진행 · 검수<span class="tab-count">${m.length}</span></a></nav>${route.tab==='quotes'?renderQuotes(p):route.tab==='milestones'?renderMilestones(p):renderOverview(p)}`}
function fact(label,value){return `<div class="fact"><label>${label}</label><div>${value||'미정'}</div></div>`}
function renderOverview(p){const selected=state.quotes.find(q=>q.id===p.selectedQuoteId);return `<div class="detail-grid"><div><section class="panel"><h2>고객의 문제와 기대</h2><h3>현재 문제</h3><p class="prose">${esc(p.problem)||'아직 정리된 문제가 없습니다'}</p><h3>요구사항 · 성공 기준</h3><p class="prose">${esc(p.requirements)||'요구사항을 입력해 주세요'}</p><h3>수요기업의 추가 조건</h3><p class="prose">${esc(p.conditions)||'등록된 추가 조건이 없습니다'}</p></section><section class="panel"><h2>프로젝트 조건</h2><div class="facts">${fact('고객 희망 예산',money(p.budget)+'원')}${fact('희망 완료일',date(p.targetDate))}${fact('우선순위',badge(p.priority,{high:'높음',medium:'보통',low:'낮음'}))}${fact('서비스 유형',serviceTypes[p.serviceType]||'AX 구축')}</div>${p.serviceType==='education'?`<h3>교육 요청</h3><div class="facts">${fact('대상 / 인원',esc(p.audience||'미정')+' / '+money(p.participantCount)+'명')}${fact('수준',esc(p.skillLevel||'미정'))}${fact('교육 방식 / 시간',({online:'온라인',offline:'오프라인',hybrid:'혼합'}[p.deliveryMode]||'미정')+' / '+money(p.trainingHours)+'시간')}${fact('장소',esc(p.location||'미정'))}</div><h3>교육 목표</h3><p class="prose">${esc(p.learningGoal||'미정')}</p><h3>희망 주제</h3><p class="prose">${esc(p.topics||'미정')}</p>`:p.serviceType==='infrastructure'?`<h3>도입 목적</h3><p class="prose">${esc(p.infrastructurePurpose||'미정')}</p><h3>기존 환경</h3><p class="prose">${esc(p.existingEnvironment||'미정')}</p><h3>설치 장소</h3><p class="prose">${esc(p.installationSite||'미정')}</p>`:''}</section><section class="panel"><div class="section-title"><h2>상담 메모</h2>${iconBtn('edit-project','상담 메모 수정','edit',`data-id="${p.id}"`)}</div><p class="prose">${esc(p.note)||'상담에서 확인한 내용을 남겨 보세요'}</p></section></div><div><section class="panel"><h2>현재 진행 단계</h2><div class="stage-flow">${Object.entries(stages).map(([s,l])=>`<div class="stage-step ${s===p.stage?'active':''}">${l}</div>`).join('')}</div><label class="sr-only" for="project-stage">진행 단계 변경</label><select id="project-stage" class="filter full" data-id="${p.id}">${options(stages,p.stage)}</select><p class="stage-hint">진행 전 공급사 견적을 선택하고, 모든 결과물을 검수한 뒤 완료로 전환하세요</p>${selected?`<div class="quote-selected">선택 견적 · ${esc(supplier(selected.supplierId)?.name||'공급사')} / ${money(selected.amount)}원</div>`:'<div class="notice-small">아직 선택된 견적이 없습니다</div>'}</section><section class="panel"><h2>고객 담당자</h2><div class="contact-name">${esc(p.contactName||'담당자 미정')}</div><div class="contact-company">${esc(p.company)} · ${esc(p.contactRole||'직책 미정')}</div><p class="prose spaced">${esc(p.contactEmail||'이메일 미등록')}</p></section><section class="panel"><div class="section-title"><h2>다음 할 일</h2>${iconBtn('new-task','할 일 추가','plus',`data-project="${p.id}"`)}</div>${tasksFor(p.id).map(t=>taskRow(t,true)).join('')||'<p class="notice-small">다음 행동을 등록해 상담을 이어가세요</p>'}</section></div></div>`}
function renderCompare(){const p=project(route.id||comparisonId)||state.projects.find(p=>p.stage==='quotation')||state.projects[0];if(p)comparisonId=p.id;return `${pageHead('MAKE THE RIGHT CONNECTION','견적 비교','공급 범위와 비용을 같은 기준으로 비교하세요',p?btn('new-quote','견적 등록','primary','plus',`data-project="${p.id}"`):'')}${p?`<div class="quote-context"><div><label for="comparison-project">비교할 프로젝트</label><select class="filter" id="comparison-project">${state.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.company)} · ${esc(x.name)}</option>`).join('')}</select></div><div><label>고객 희망 예산</label><strong>${money(p.budget)}<span> 원</span></strong></div><div><label>서비스</label><span>${serviceTypes[p.serviceType]||'AX 구축'}</span></div></div>${renderQuotes(p,true)}`:empty('프로젝트를 먼저 등록하세요','프로젝트에 연결된 공급사 견적을 비교할 수 있습니다',btn('new-project','프로젝트 등록','primary','plus'))}`}
function renderQuotes(p,global=false){const qs=quotesFor(p.id);return `${!global?`<div class="toolbar quote-toolbar"><div class="section-title"><h2>공급사 제안 비교</h2><p>희망 예산 ${money(p.budget)}원</p></div>${btn('new-quote','견적 등록','primary small','plus',`data-project="${p.id}"`)}</div>`:''}${qs.length?`<div class="comparison">${qs.map(q=>{const s=supplier(q.supplierId);const selected=q.id===p.selectedQuoteId;return `<article class="quote-card ${selected?'is-selected':''}">${selected?'<div class="quote-selected">✓ 내부 선택 견적 · 계약 체결 여부는 별도 확인</div>':''}<div class="quote-card-head"><div class="quote-card-top">${badge(q.status,{received:'견적 접수',requested:'요청 중'})}${demo(q)}</div><h3>${esc(s?.name||'미지정 공급사')}</h3><p>${esc(s?.specialty||'')}</p><div class="quote-price">${won(q.amount)}</div><div class="${q.amount>p.budget?'over-budget':'under-budget'}">${q.amount>p.budget?`희망 예산 대비 ${money(q.amount-p.budget)}원 초과`:`희망 예산 이내 · ${money(p.budget-q.amount)}원 여유`}</div></div><div class="quote-body">${quoteField('예상 기간',`${q.durationWeeks}주${q.trainingHours?` · 교육 ${q.trainingHours}시간`:''}`)}${quoteField('포함 범위',q.scope)+(p.serviceType==='infrastructure'?quoteField('사양 · 수량',`${q.specifications||'미정'}\n${q.quantity||0}대`)+quoteField('설치비 (총액에 포함)',`${money(q.installationCost||0)}원`)+quoteField('납기 · 보증',`${q.deliveryDate||'납기 미정'}\n${q.warranty||'미정'}`):'')}${p.serviceType==='education'?quoteField('커리큘럼',q.curriculum)+quoteField('실습 · 강사',`${q.practice||'미정'}\n${q.instructor||'강사 미정'}`):''}${quoteField('제외 항목 · 추가 비용',q.exclusions)}${quoteField(p.serviceType==='education'?'교육 후 지원':'유지보수 · 운영 지원',q.maintenance)}${quoteField('견적 유효일',q.validUntil?date(q.validUntil):'미정',true)}</div><div class="quote-actions">${btn('select-quote',selected?'선택 취소':'이 견적 선택',selected?'soft':'', '',`data-id="${q.id}" ${q.status!=='received'?'disabled':''}`)}${iconBtn('edit-quote','견적 수정','edit',`data-id="${q.id}"`)}${iconBtn('delete-quote','견적 삭제','trash',`data-id="${q.id}"`)}</div></article>`}).join('')}</div>`:empty('비교할 견적이 없습니다','공급사별 제안 금액과 범위를 입력해 보세요',btn('new-quote','첫 견적 등록','primary','plus',`data-project="${p.id}"`))}<p class="quote-footnote">가상 견적은 화면 시연용이며 실제 공급사의 가격이나 제안이 아닙니다. 금액은 동일한 부가세 기준으로 입력하고, 포함 범위·별도 비용을 확인하세요. 견적 선택은 내부 기록이며 계약 또는 외부 연락이 실행되지 않습니다</p>`}
function quoteField(l,v,raw=false){return `<div class="quote-field"><label>${l}</label><div>${raw?v:esc(v||'미정')}</div></div>`}
function renderMilestones(p){const ms=milestonesFor(p.id),approved=ms.filter(m=>m.status==='approved').length;return `<div class="toolbar"><div class="section-title"><h2>단계별 결과물과 검수</h2></div>${btn('new-milestone','결과물 추가','primary small','plus',`data-project="${p.id}"`)}</div><div class="milestone-progress"><strong>${approved}<small> / ${ms.length}</small></strong><div class="progress-track" aria-label="검수 완료율 ${ms.length?Math.round(approved/ms.length*100):0}%"><div style="width:${ms.length?approved/ms.length*100:0}%"></div></div><span>검수 완료</span></div>${ms.map((m,i)=>`<article class="milestone ${m.status}"><div class="milestone-number">${m.status==='approved'?icon('check'):String(i+1).padStart(2,'0')}</div><div><div class="milestone-head"><div><h3>${esc(m.title)}</h3><p>예정일 ${date(m.dueDate)} ${due(m.dueDate)}</p></div><div>${badge(m.status,milestoneStatus)}${iconBtn('edit-milestone','결과물 수정','edit',`data-id="${m.id}"`)}</div></div><div class="milestone-content"><div><label>제출 결과물 · 위치</label><div>${esc(m.deliverable||'미등록')}</div></div><div><label>검수 기준</label><div>${esc(m.acceptanceCriteria||'기준을 작성해 주세요')}</div></div></div>${m.reviewNote?`<div class="review-note">검수 메모 · ${esc(m.reviewNote)}</div>`:''}<div class="milestone-actions">${m.status==='planned'||m.status==='revision'?btn('review-milestone','제출 · 검수 요청','small','',`data-id="${m.id}" data-status="submitted"`):''}${m.status==='submitted'?btn('review-milestone','수정 요청','small','',`data-id="${m.id}" data-status="revision"`)+btn('review-milestone','검수 완료','soft small','check',`data-id="${m.id}" data-status="approved"`):''}${m.status==='approved'&&p.stage!=='completed'?btn('review-milestone','검수 다시 열기','small','',`data-id="${m.id}" data-status="submitted"`):''}${iconBtn('delete-milestone','결과물 삭제','trash',`data-id="${m.id}"`)}</div></div></article>`).join('')||empty('등록된 결과물이 없습니다','단계마다 납품할 결과물과 완료 기준을 정해 보세요')}${ms.length&&approved===ms.length&&p.stage!=='completed'?`<div class="panel"><div class="section-title"><div><h2>모든 결과물의 검수가 끝났습니다</h2><p>고객 확인과 미결 사항을 점검한 뒤 완료 처리하세요</p></div>${btn('complete-project','프로젝트 완료','primary','check',`data-id="${p.id}"`)}</div></div>`:''}<p class="notice-small">검수는 내부 운영 기록입니다. 실제 파일 업로드·고객 서명·결제 처리는 포함하지 않습니다</p>`}
function taskRow(t,editable){const p=project(t.projectId);return `<div class="todo-item ${t.done?'done':''}"><button class="check ${t.done?'done':''}" type="button" data-action="toggle-task" data-id="${t.id}" aria-label="${esc(t.title)} ${t.done?'미완료로':'완료로'} 변경" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="todo-body"><div class="todo-name">${esc(t.title)}</div><div class="todo-sub">${p?`<a href="#projects/${p.id}">${esc(p.company)}</a>`:'일반 운영'}<span>· ${shortDate(t.dueDate)}</span>${!t.done?due(t.dueDate):''}</div></div>${editable?`<div class="tasks-controls">${iconBtn('edit-task','할 일 수정','edit',`data-id="${t.id}"`)}${iconBtn('delete-task','할 일 삭제','trash',`data-id="${t.id}"`)}</div>`:''}</div>`}
function renderTasks(){const ts=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done)).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));return `${pageHead('KEEP THINGS MOVING','다음 할 일','프로젝트마다 다음 행동과 기한을 명확하게',btn('new-task','할 일 추가','primary','plus'))}<div class="toolbar"><div class="segmented">${[['open','남은 할 일'],['done','완료한 일'],['all','전체']].map(([v,l])=>`<button type="button" data-action="task-filter" data-value="${v}" class="${taskFilter===v?'active':''}">${l}</button>`).join('')}</div><span class="muted">${ts.length}건</span></div><section class="panel task-page">${ts.map(t=>taskRow(t,true)).join('')||empty('표시할 할 일이 없습니다','필터를 바꾸거나 새로운 할 일을 추가해 보세요')}</section>`}
function renderSuppliers(){return `${pageHead('YOUR PARTNER NETWORK','공급사','AX 구축과 AI 교육을 연결할 파트너 후보를 관리하세요',btn('new-supplier','공급사 등록','primary','plus'))}<div class="warning">르몽·어크로스·스파르타·에이블런·세계경영연구회는 사용자 지정 후보입니다. 협업 확정, 법인명·담당자·상품·가격 검증을 의미하지 않습니다</div><div class="suppliers-grid">${state.suppliers.map(s=>`<article class="supplier-card"><div class="supplier-top"><div class="supplier-logo">${esc(s.name.replace('가상 ','').slice(0,1))}</div><div>${badge(s.relationship,{candidate:'후보 · 미확정',confirmed:'협업 확인'})}${iconBtn('edit-supplier','공급사 수정','edit',`data-id="${s.id}"`)}</div></div><h2>${esc(s.name)}${demo(s)}</h2><p>${esc(s.specialty||'전문 분야 미등록')}</p><div class="tags">${(s.serviceTypes||['ax']).map(t=>`<span class="tag">${serviceTypes[t]}</span>`).join('')}${(s.industries||[]).map(i=>`<span class="tag">${esc(i)}</span>`).join('')}</div><p>${esc(s.note||'추가 확인이 필요합니다')}</p><div class="supplier-meta"><span>담당 · ${esc(s.contactName||'미확인')}</span><span>등록 견적 ${state.quotes.filter(q=>q.supplierId===s.id).length}건</span></div></article>`).join('')||empty('등록된 공급사가 없습니다','검토 중인 후보부터 등록해 보세요')}</div><p class="contract-note">공급사 등록은 내부 기록입니다. 알림 발송, 자동 매칭, 협약 체결은 실행되지 않습니다</p>`}
function renderSettings(){return `${pageHead('WORKSPACE DATA','데이터 관리','내 컴퓨터에 저장되는 단일 운영자용 검토 환경')}<div class="warning">이 버전에는 로그인·사용자 권한·운영 감사로그가 없습니다. 서버는 기본적으로 이 컴퓨터에서만 접근 가능합니다. 인터넷에 공개하거나 실제 고객의 민감정보를 입력하지 마세요</div><div class="settings-grid"><section class="panel"><h2>저장 방식과 백업</h2><p>입력 내용은 실행 중인 서버의 SQLite 데이터베이스에 저장됩니다. 브라우저를 새로 열거나 서버를 재시작해도 기록은 유지됩니다</p><div class="settings-buttons"><a class="btn" href="/api/export" download="ax-bridge-backup.json">${icon('download')}JSON 백업 받기</a>${btn('import','백업 불러오기','','upload')}</div><p class="arch">불러오면 현재 프로젝트·공급사·견적·결과물·할 일이 전부 교체됩니다. 먼저 백업을 내려받으세요. 백업 파일은 외부 서비스로 전송되지 않습니다</p></section><section class="panel"><h2>시연 데이터</h2><p>현재 ${state.projects.length}개 프로젝트, ${state.suppliers.length}개 공급사, ${state.quotes.length}개 견적이 저장되어 있습니다. 시연 데이터 초기화는 지금까지 입력한 내용을 지우고 가상 사례로 바꿉니다</p>${btn('reset','시연 데이터로 초기화','danger')}<p class="arch">샘플 고객과 모든 샘플 견적은 가상입니다. 후보 업체의 실제 영업 제안이나 가격을 의미하지 않습니다</p></section><section class="panel"><h2>정식 운영 전 필요한 것</h2><p>로그인과 역할별 권한, 호스팅·접근제어, 데이터 백업·복구, 변경 이력, 파일 저장소, 개인정보 처리 방침을 준비해야 합니다. 다중 사용자 동시 편집과 실제 계정 인증은 후속 범위입니다. 역할별 화면과 검토용 가입은 실제 권한 체계가 아닙니다</p></section><section class="panel"><h2>중개를 위한 공통 흐름</h2><p>상담 → 견적 비교 → 공급사 선택 → 진행 → 단계별 검수 → 완료</p><p>AX 구축은 요구사항과 납품 범위를, AI 교육은 대상·학습 목표와 커리큘럼을 중심으로 비교합니다. AI 교육은 외부 교육업체를 연결하는 중개 모델입니다</p></section></div><input type="file" id="import-file" accept="application/json,.json" hidden>`}
function options(map,current){return Object.entries(map).map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('')}
function field(label,name,value='',type='text',extra='',wide=false){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function area(label,name,value='',wide=true,extra=''){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`}
function selectField(label,name,map,value='',wide=false){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options(map,value)}</select></div>`}
function formDialog(title,subtitle,content,onSave,{submit='저장',extra=''}={}){modal.innerHTML=`<form id="record-form"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${iconBtn('close-modal','닫기','close')}</div><div class="modal-body"><div class="form-grid">${content}</div><div id="form-error" class="form-error" role="alert" hidden></div></div><div class="modal-footer"><span class="modal-note">이 워크스페이스에만 저장됩니다</span><div>${extra}${btn('close-modal','취소')}<button type="submit" class="btn primary">${submit}</button></div></div></form>`;modal.showModal();const form=$('#record-form');form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const b=$('[type=submit]',form);b.disabled=true;$('#form-error').hidden=true;try{const values=Object.fromEntries(new FormData(form));for(const [key,value] of Object.entries(values))if(typeof value==='string')values[key]=value.trim();for(const field of form.querySelectorAll('[required]'))if(typeof values[field.name]==='string'&&!values[field.name])throw Error('필수 항목에 공백만 입력할 수 없습니다.');await onSave(values);modal.close();try{await refresh();toast('저장했습니다')}catch(error){app.innerHTML='<div role="alert">저장 완료 · 화면 갱신 실패. 다시 조회해 주세요. <button type="button" data-action="retry-refresh">다시 조회</button></div>';toast('저장은 완료됐지만 화면 갱신에 실패했습니다. 다시 조회해 주세요.',true)}}catch(err){$('#form-error').textContent=err.message;$('#form-error').hidden=false;}finally{busy=false;b.disabled=false}})}
function educationFields(p){return `<div class="field wide"><div class="notice-small">외부 교육업체 연결을 위한 요청 조건입니다</div></div>${field('교육 대상','audience',p.audience,'text','maxlength="300"')}${field('참여 인원','participantCount',p.participantCount||0,'number','min="0" step="1"')}${field('현재 수준','skillLevel',p.skillLevel,'text','placeholder="예: 생성형 AI 입문" maxlength="300"')}${selectField('교육 방식','deliveryMode',{online:'온라인',offline:'오프라인',hybrid:'혼합'},p.deliveryMode||'online')}${field('총 교육 시간','trainingHours',p.trainingHours||0,'number','min="0" step="0.5"')}${field('장소 / 접속 방식','location',p.location,'text','maxlength="500"')}${area('교육 목표','learningGoal',p.learningGoal)}${area('희망 주제','topics',p.topics)}`}
function openProject(id){const p=project(id)||{priority:'medium',serviceType:'ax',budget:0,isDemo:false};const content=selectField('서비스 유형','serviceType',serviceTypes,p.serviceType||'ax')+selectField('우선순위','priority',{high:'높음',medium:'보통',low:'낮음'},p.priority)+field('프로젝트명 *','name',p.name,'text','required maxlength="200"',true)+field('고객사명 *','company',p.company,'text','required maxlength="200"')+field('업종','industry',p.industry,'text','placeholder="예: 이커머스, 제조업" maxlength="100"')+field('고객 담당자','contactName',p.contactName,'text','maxlength="100"')+field('직책','contactRole',p.contactRole,'text','maxlength="100"')+field('연락 이메일','contactEmail',p.contactEmail,'email','maxlength="254"',true)+field('희망 예산 (원)','budget',p.budget,'number','min="0" max="1000000000000000" step="1" required')+field('희망 완료일','targetDate',p.targetDate,'date')+area('현재 문제','problem',p.problem)+area('요구사항 · 성공 기준','requirements',p.requirements)+area('수요기업의 추가 조건','conditions',p.conditions)+`<div id="education-fields" class="field wide"><div class="form-grid">${educationFields(p)}</div></div>`+`<div id="infrastructure-fields" class="field wide"><div class="form-grid">${area('도입 목적','infrastructurePurpose',p.infrastructurePurpose)}${area('기존 환경','existingEnvironment',p.existingEnvironment)}${field('설치 장소','installationSite',p.installationSite,'text','maxlength="500"',true)}</div></div>`+selectField('영업담당자','ownerId',{'':'미배정',...Object.fromEntries((state.salespeople||[]).map(s=>[s.id,s.name]))},p.ownerId||'',true)+area('상담 메모','note',p.note)+`<label class="checkbox-field field wide"><input type="checkbox" name="isDemo" ${p.isDemo?'checked':''}>가상 프로젝트로 표시</label>`;formDialog(id?'프로젝트 수정':'새 프로젝트','고객의 요청부터 다음 연결의 기준을 만듭니다',content,async d=>{d.budget=Number(d.budget);d.participantCount=Number(d.participantCount);d.trainingHours=Number(d.trainingHours);d.isDemo=d.isDemo==='on';if(operatorMode==='sales')delete d.ownerId;const saved=await api(`projects${id?'/'+id:''}`,id?'PATCH':'POST',d);if(!id)location.hash=`projects/${saved.id}`});const set=()=>{$('#education-fields').hidden=$('#f-serviceType').value!=='education';$('#infrastructure-fields').hidden=$('#f-serviceType').value!=='infrastructure'};$('#f-serviceType').addEventListener('change',set);set();if(operatorMode==='sales')$('#f-ownerId').disabled=true;}
function openSupplier(id){const s=supplier(id)||{relationship:'candidate',serviceTypes:['ax']};formDialog(id?'공급사 수정':'공급사 등록','실제 확인한 정보와 검토 중인 정보를 구분해 주세요',field('공급사명 *','name',s.name,'text','required maxlength="200"')+selectField('담당 영업자','ownerId',{'':'미배정',...Object.fromEntries((state.salespeople||[]).map(s=>[s.id,s.name]))},s.ownerId||'')+selectField('관계 상태','relationship',{candidate:'후보 · 미확정',confirmed:'협업 확인'},s.relationship)+field('전문 분야','specialty',s.specialty,'text','maxlength="500"',true)+field('주요 업종 (쉼표로 구분)','industries',(s.industries||[]).join(', '),'text','maxlength="500"',true)+field('확인된 담당자','contactName',s.contactName,'text','maxlength="100"')+selectField('공급 서비스','services',{ax:'AX 구축',education:'AI 교육',infrastructure:'AI 인프라',both:'AX 구축 + AI 교육',axinfra:'AX 구축 + AI 인프라',eduinfra:'AI 교육 + AI 인프라',all:'구축 + 교육 + 인프라'},s.serviceTypes?.length===3?'all':s.serviceTypes?.length===2?(s.serviceTypes.includes('infrastructure')?(s.serviceTypes.includes('ax')?'axinfra':'eduinfra'):'both'):s.serviceTypes?.[0]||'ax')+area('확인 내용 · 메모','note',s.note)+`<label class="checkbox-field field wide"><input type="checkbox" name="isDemo" ${s.isDemo?'checked':''}>가상 공급사로 표시</label>`,async d=>{d.industries=d.industries.split(',').map(x=>x.trim()).filter(Boolean);d.serviceTypes=d.services==='all'?['ax','education','infrastructure']:d.services==='both'?['ax','education']:d.services==='axinfra'?['ax','infrastructure']:d.services==='eduinfra'?['education','infrastructure']:[d.services];delete d.services;d.isDemo=d.isDemo==='on';await api(`suppliers${id?'/'+id:''}`,id?'PATCH':'POST',d)},{extra:id?btn('delete-supplier','삭제','danger','',`data-id="${id}"`):''})}
function openQuote(id,projectId){const q=state.quotes.find(q=>q.id===id)||{projectId,amount:0,durationWeeks:4,status:'received',isDemo:false};const p=project(q.projectId);if(!p)return toast('프로젝트를 먼저 선택해 주세요',true);if(!state.suppliers.length)return toast('공급사를 먼저 등록해 주세요',true);formDialog(id?'견적 수정':'견적 등록',`${p.company} · ${p.name}`,selectField('공급사 *','supplierId',Object.fromEntries(state.suppliers.map(s=>[s.id,s.name])),q.supplierId)+selectField('견적 상태','status',{requested:'요청 중',received:'견적 접수'},q.status)+field('총 제안 금액 (원) *','amount',q.amount,'number','required min="0" max="1000000000000000" step="1"')+field('예상 기간 (주)','durationWeeks',q.durationWeeks,'number','min="0" max="520" step="0.5" required')+field('견적 유효일','validUntil',q.validUntil,'date','',true)+area('포함 범위','scope',q.scope)+area('제외 항목 · 추가 비용 / 부가세 기준','exclusions',q.exclusions)+area(p.serviceType==='education'?'교육 후 지원':'유지보수 · 운영 지원','maintenance',q.maintenance)+(p.serviceType==='education'?field('총 교육 시간','trainingHours',q.trainingHours||0,'number','min="0" step="0.5"',true)+area('커리큘럼','curriculum',q.curriculum)+area('실습 방식 · 산출물','practice',q.practice)+field('강사 조건','instructor',q.instructor,'text','maxlength="500"',true):p.serviceType==='infrastructure'?area('장비 / 서버 사양','specifications',q.specifications)+field('수량','quantity',q.quantity||0,'number','min="0" step="1"')+field('설치비 (총 제안 금액에 포함)','installationCost',q.installationCost||0,'number','min="0" step="1"')+field('희망 납기','deliveryDate',q.deliveryDate,'date','',true)+area('보증 조건','warranty',q.warranty):'')+`<div class="field wide">고객 공유: ${q.sharedWithBuyer?'공유 중':'영업 검토 대기'} · 내용 변경 시 공유 해제${id?btn('share-quote',q.sharedWithBuyer?'공유 해제':'검토 완료 · 고객 공유','','',`data-id="${q.id}"`):''}</div><label class="checkbox-field field wide"><input type="checkbox" name="isDemo" ${q.isDemo?'checked':''}>가상 견적으로 표시</label>`,async d=>{d.projectId=p.id;d.amount=Number(d.amount);d.durationWeeks=Number(d.durationWeeks);d.trainingHours=Number(d.trainingHours||0);d.quantity=Number(d.quantity||0);d.installationCost=Number(d.installationCost||0);d.isDemo=d.isDemo==='on';await api(`quotes${id?'/'+id:''}`,id?'PATCH':'POST',d)})}
function openMilestone(id,projectId){const m=state.milestones.find(m=>m.id===id)||{projectId};formDialog(id?'결과물 수정':'단계별 결과물 추가','납품할 내용과 검수 기준을 함께 정의하세요',field('단계 / 결과물 이름 *','title',m.title,'text','required maxlength="200"',true)+field('예정일','dueDate',m.dueDate,'date','',true)+area('제출 결과물 · 파일 위치','deliverable',m.deliverable)+area('검수 기준','acceptanceCriteria',m.acceptanceCriteria)+area('검수 메모','reviewNote',m.reviewNote),async d=>api(`milestones${id?'/'+id:''}`,id?'PATCH':'POST',{...d,projectId:m.projectId}))}
function openReview(id,status){const m=state.milestones.find(m=>m.id===id);if(!m)return;formDialog(milestoneStatus[status],m.title,(status==='submitted'?area('제출 결과물 · 파일 위치 *','deliverable',m.deliverable,true,'required'):'')+area(status==='revision'?'수정 요청 사유 *':'검수 메모', 'reviewNote',m.reviewNote,true,status==='revision'?'required':''),async d=>api(`milestones/${id}`,'PATCH',{...d,status}),{submit:milestoneStatus[status]})}
function openTask(id,projectId){const t=state.tasks.find(t=>t.id===id)||{projectId:projectId||state.projects[0]?.id||''};if(!state.projects.length)return toast('할 일을 연결할 프로젝트를 먼저 등록해 주세요',true);formDialog(id?'할 일 수정':'다음 할 일 추가','다음 행동과 기한을 정해 두세요',selectField('연결 프로젝트','projectId',Object.fromEntries(state.projects.map(p=>[p.id,`${p.company} · ${p.name}`])),t.projectId,true)+field('할 일 *','title',t.title,'text','required maxlength="200"',true)+field('기한','dueDate',t.dueDate,'date','',true),async d=>api(`tasks${id?'/'+id:''}`,id?'PATCH':'POST',d))}
function confirmDialog(title,text,fn,label='확인',danger=false){if(modal.open)modal.close();formDialog(title,'',`<div class="field wide"><p class="confirm-text">${esc(text)}</p></div>`,fn,{submit:label});if(danger)$('[type=submit]',modal).classList.add('danger')}
async function mutate(path,method,data,message='변경했습니다'){if(busy)return;busy=true;try{await api(path,method,data);await refresh();toast(message)}catch(err){toast(err.message,true)}finally{busy=false}}
app.addEventListener('input',e=>{if(e.target.id==='project-search'){filters.search=e.target.value;$('#project-results').innerHTML=projectResults(filteredProjects())}});
app.addEventListener('change',async e=>{const t=e.target;const filterIds={'stage-filter':'stage','industry-filter':'industry','service-filter':'serviceType'};if(filterIds[t.id]){filters[filterIds[t.id]]=t.value;$('#project-results').innerHTML=projectResults(filteredProjects())}if(t.id==='comparison-project'){comparisonId=t.value;location.hash=`compare/${t.value}`}if(t.id==='project-stage'){const p=project(t.dataset.id),chosen=t.value;t.value=p.stage;const apply=()=>mutate(`projects/${p.id}`,'PATCH',{stage:chosen});if(chosen==='completed')confirmDialog('프로젝트를 완료할까요?','모든 결과물의 검수가 끝났는지 확인합니다. 완료 상태는 이후 다시 변경할 수 있습니다.',()=>api(`projects/${p.id}`,'PATCH',{stage:chosen}),'완료 처리');else await apply()}if(t.id==='import-file'){const file=t.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('1MB 이하의 JSON 백업만 불러올 수 있습니다.');const parsed=JSON.parse(await file.text());if(!parsed.state)throw Error('AX브릿지 백업 파일 형식이 아닙니다.');confirmDialog('백업으로 데이터를 교체할까요?','현재 모든 데이터가 선택한 백업 내용으로 교체됩니다. 기존 데이터는 JSON 백업으로 내려받은 경우에만 복구할 수 있습니다.',()=>api('import','POST',{schemaVersion:parsed.schemaVersion,state:parsed.state}),'전체 교체',true)}catch(err){toast(err.message,true)}t.value=''}});
document.addEventListener('click',async e=>{const link=e.target.closest('[data-stage-filter]');if(link)filters.stage=link.dataset.stageFilter;const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,pid=el.dataset.project;
if(a==='close-modal'){if(!busy)modal.close();return}if(busy)return;
if(a==='new-project')return openProject();if(a==='edit-project')return openProject(id);
if(a==='new-supplier')return openSupplier();if(a==='edit-supplier')return openSupplier(id);
if(a==='new-quote')return openQuote(null,pid);if(a==='edit-quote')return openQuote(id);
if(a==='new-milestone')return openMilestone(null,pid);if(a==='edit-milestone')return openMilestone(id);
if(a==='new-task')return openTask(null,pid);if(a==='edit-task')return openTask(id);
if(a==='review-milestone')return openReview(id,el.dataset.status);
if(a==='view-board'||a==='view-list'){filters.view=a.slice(5);render();return}
if(a==='task-filter'){taskFilter=el.dataset.value;render();return}
if(a==='toggle-task'){const t=state.tasks.find(t=>t.id===id);return mutate(`tasks/${id}`,'PATCH',{done:!t.done},t.done?'할 일을 다시 열었습니다':'할 일을 완료했습니다')}
if(a==='select-quote'){const q=state.quotes.find(q=>q.id===id),p=project(q.projectId);if(p.selectedQuoteId===id&&p.stage==='progress')return confirmDialog('견적 선택을 해제할까요?','진행 단계도 견적 단계로 돌아갑니다.',()=>api(`projects/${p.id}`,'PATCH',{selectedQuoteId:null,stage:'quotation'}),'선택 해제');return mutate(`projects/${p.id}`,'PATCH',{selectedQuoteId:p.selectedQuoteId===id?null:id},p.selectedQuoteId===id?'견적 선택을 해제했습니다':'내부 선택 견적을 기록했습니다')}
if(a==='complete-project')return confirmDialog('프로젝트를 완료할까요?','검수 내역과 미결 사항을 확인한 뒤 완료로 전환합니다.',()=>api(`projects/${id}`,'PATCH',{stage:'completed'}),'완료 처리');
if(['delete-project','delete-supplier','delete-quote','delete-milestone','delete-task'].includes(a)){const type=a.slice(7),names={project:'프로젝트',supplier:'공급사',quote:'견적',milestone:'결과물',task:'할 일'},collection={project:'projects',supplier:'suppliers',quote:'quotes',milestone:'milestones',task:'tasks'}[type];return confirmDialog(`${names[type]}를 삭제할까요?`,type==='project'?'연결된 견적·결과물·할 일도 함께 삭제됩니다. JSON 백업이 없으면 복구할 수 없습니다.':'이 기록이 삭제됩니다. 연결된 사용 중 데이터가 있으면 삭제할 수 없습니다.',async()=>{await api(`${collection}/${id}`,'DELETE');if(type==='project')location.hash='projects'},'삭제',true)}
if(a==='import')return $('#import-file').click();
if(a==='reset')return confirmDialog('시연 데이터로 초기화할까요?','입력한 모든 내용이 삭제되고 가상 프로젝트와 샘플 견적이 다시 생성됩니다. 먼저 JSON 백업을 내려받으세요.',()=>api('reset','POST',{}),'초기화',true);
});
modal.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
modal.addEventListener('click',e=>{if(!busy&&e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
window.addEventListener('hashchange',()=>{if(modal.open&&!busy)modal.close();render();window.scrollTo(0,0)});
refresh().catch(err=>{app.innerHTML=`<div class="app-error"><h1>운영실에 연결하지 못했습니다</h1><p>${esc(err.message)}<br>실행 중인 서버가 있는지 확인해 주세요</p><button type="button" class="btn primary" id="retry">다시 연결</button> <button type="button" class="btn" id="reset-role">관리자 검토 모드</button></div>`;$('#retry').onclick=()=>location.reload();$('#reset-role').onclick=()=>{operatorMode='admin';operatorEntity='';remember('ax-operator-mode','admin');remember('ax-operator-entity','');refresh().catch(error=>toast(error.message,true))}});

// Additional brokerage workstreams share the same local data and validation flow.
const programStatuses={review:'검토 중',preparing:'신청 준비',submitted:'신청 완료',selected:'선정 기록',rejected:'미선정 기록'};
const investmentStatuses={review:'초기 검토',meeting:'미팅',diligence:'실사',decision:'결정 기록'};
function safeLink(url,label){if(!url)return '<span class="muted">미등록 · 확인 필요</span>';try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '<span class="muted">유효한 링크가 아닙니다</span>';return `<a class="text-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`}catch{return '<span class="muted">유효한 링크가 아닙니다</span>'}}
let programView='company';
const isReferenceProgram=p=>/예산|budget|주관|기관|operator|agency/.test(`${p.documentType||''} ${p.applicantType||''}`);
function renderPrograms(){const allPrograms=state.programs||[],ps=allPrograms.filter(p=>programView==='reference'?isReferenceProgram(p):!isReferenceProgram(p)),apps=state.applications||[];return `${pageHead('SUPPORT PROGRAMS','지원사업 관리','공식 공고 확인부터 고객별 신청 진행 기록까지',btn('new-program','지원사업 등록','primary','plus'))}<div class="warning">AI 바우처·소상공인 AI·혁신바우처는 관리 유형 예시입니다. 공식자료는 표시된 확인 시점 기준이며 최신 모집 여부는 원문을 확인해야 합니다. 가상 공고는 미검증입니다. 예산자료의 총액은 기업당 지원한도가 아니며, 자격 충족·선정을 보장하지 않습니다</div><div class="toolbar"><div class="segmented"><button type="button" data-action="program-view" data-value="company" class="${programView==='company'?'active':''}">기업 신청 공고 ${allPrograms.filter(p=>!isReferenceProgram(p)).length}</button><button type="button" data-action="program-view" data-value="reference" class="${programView==='reference'?'active':''}">예산 · 기관 모집 참고자료 ${allPrograms.filter(isReferenceProgram).length}</button></div></div><div class="suppliers-grid">${ps.map(p=>`<article class="supplier-card"><div class="supplier-top"><span class="tag">${p.year}년</span><div>${badge(p.verification,{unverified:'미검증',verified:'공식 확인 기록'})}${iconBtn('edit-program','지원사업 수정','edit',`data-id="${p.id}"`)}</div></div><h2 class="spaced">${esc(p.name)}${demo(p)}</h2><div class="tags"><span class="tag">${esc(p.documentType||'가상 모집공고')}</span><span class="tag">${esc(p.status||'모집상태 미확인')}</span></div><p>${esc(p.benefit||'지원 내용 미등록')}</p><div class="facts">${fact('접수 기간',date(p.startDate)+' ~ '+date(p.endDate))}${fact('자부담 조건',esc(p.selfContribution||'확인 필요'))}</div><h3 class="row-sub spaced">지원 대상 요건</h3><p>${esc(p.eligibility||'확인 필요')}</p>${safeLink(p.officialUrl,'공식 자료 보기')}<div class="notice-small">${p.checkedAt?'확인 기준: '+esc(p.checkedAt):'출처 검증 필요'}<br>${esc(p.statusEvidence||'')}</div><p class="spaced">${esc(p.note||'')}</p>${!isReferenceProgram(p)?btn('new-application','고객 의뢰 연결','small','plus',`data-program="${p.id}"`):'<span class="tag">신청용이 아닌 정책 참고자료</span>'}</article>`).join('')||empty('등록된 지원사업이 없습니다','공식 출처와 확인한 연도를 함께 남겨 주세요')}</div><div class="section-title spaced"><h2>고객별 검토 · 신청 현황</h2>${btn('new-application','연결 추가','small','plus')}</div>${apps.length?`<div class="table-wrap"><table><thead><tr><th>고객 / 프로젝트</th><th>지원사업</th><th>진행 상태</th><th>다음 할 일</th><th>기한</th><th>관리</th></tr></thead><tbody>${apps.map(a=>`<tr><td><a href="#projects/${a.projectId}">${esc(project(a.projectId)?.company||'미확인')}</a><div class="row-sub">${esc(project(a.projectId)?.name||'')}</div></td><td>${esc(allPrograms.find(p=>p.id===a.programId)?.name||'미확인')}</td><td>${badge(a.status,programStatuses)}</td><td>${esc(a.nextAction||'미등록')}<div class="row-sub">${esc(a.note||'')}</div></td><td>${date(a.dueDate)} ${due(a.dueDate)}</td><td>${iconBtn('edit-application','신청 기록 수정','edit',`data-id="${a.id}"`)}${iconBtn('delete-application','신청 기록 삭제','trash',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('연결된 신청 기록이 없습니다','공고와 고객의 구축·교육·인프라 의뢰를 연결해 관리합니다')}<p class="notice-small">관리자가 입력한 내부 진행 기록입니다. 자동 신청·서류 제출·외부 연락은 실행되지 않습니다</p>`}
function openProgram(id){const p=(state.programs||[]).find(x=>x.id===id)||{year:new Date().getFullYear(),verification:'unverified',isDemo:false};formDialog(id?'지원사업 수정':'지원사업 등록','현행 공고는 공식 출처에서 직접 확인한 후 기록해 주세요',field('사업명 *','name',p.name,'text','required maxlength="200"',true)+field('연도','year',p.year,'number','min="1900" max="9999" required')+selectField('검증 상태','verification',{unverified:'미검증',verified:'공식 출처 확인'},p.verification)+field('공식 공고 URL','officialUrl',p.officialUrl,'url','placeholder="https://"',true)+field('자료 유형','documentType',p.documentType,'text','placeholder="모집공고 / 확정예산 / 예산안"')+field('대상 유형','applicantType',p.applicantType,'text','placeholder="수요기업 / 주관기관"')+field('공고 상태 (확인 시점)','status',p.status,'text','placeholder="접수기간 내 / 마감 / 세부공고 전"')+field('확인 기준일','checkedAt',p.checkedAt,'text','placeholder="2026-10-05 KST"')+area('상태 확인 근거','statusEvidence',p.statusEvidence)+field('접수 시작일','startDate',p.startDate,'date')+field('접수 마감일','endDate',p.endDate,'date')+area('대상 요건','eligibility',p.eligibility)+area('지원 내용','benefit',p.benefit)+area('자부담 · 제한 조건','selfContribution',p.selfContribution)+area('확인 메모','note',p.note)+`<label class="checkbox-field field wide"><input type="checkbox" name="isDemo" ${p.isDemo?'checked':''}>가상 공고로 표시</label>`,d=>api(`programs${id?'/'+id:''}`,id?'PATCH':'POST',{...d,year:Number(d.year),isDemo:d.isDemo==='on'}),{extra:id?btn('delete-program','삭제','danger','',`data-id="${id}"`):''})}
function openApplication(id,programId){const a=(state.applications||[]).find(x=>x.id===id)||{programId,status:'review'};if(!(state.programs||[]).length||!state.projects.length)return toast('지원사업과 프로젝트를 먼저 등록해 주세요',true);formDialog(id?'고객별 신청 기록 수정':'지원사업과 고객 연결','자격 판단과 제출 여부는 사람이 확인하는 내부 기록입니다',selectField('지원사업','programId',Object.fromEntries(state.programs.filter(p=>!isReferenceProgram(p)).map(p=>[p.id,p.name])),a.programId,true)+selectField('연결 프로젝트','projectId',Object.fromEntries(state.projects.map(p=>[p.id,`${p.company} · ${p.name}`])),a.projectId,true)+selectField('진행 상태','status',programStatuses,a.status)+field('다음 행동 기한','dueDate',a.dueDate,'date')+field('다음 할 일','nextAction',a.nextAction,'text','maxlength="500"',true)+area('검토 · 신청 메모','note',a.note),d=>api(`applications${id?'/'+id:''}`,id?'PATCH':'POST',d))}
function renderInvestments(){const list=state.investments||[];return `${pageHead('ADMIN-ONLY OPPORTUNITIES','투자 검토 CRM','직접 투자 검토와 투자자 연결을 분리해 기록합니다',btn('new-investment','후보 등록','primary','plus'))}<div class="warning">관리자 전용 내부 기록입니다. 가상 후보는 실제 투자 대상이 아닙니다. 투자 추천·공개 모집·계약·송금·금융거래 기능은 제공하지 않습니다</div><div class="kanban">${Object.entries(investmentStatuses).map(([s,l])=>`<section class="kanban-col"><div class="kanban-head"><strong>${l}</strong><span>${list.filter(i=>i.status===s).length}건</span></div>${list.filter(i=>i.status===s).map(i=>`<article class="project-card"><div class="card-top"><span class="tag">${i.mode==='direct'?'직접 투자 검토':'투자자 연결'}</span>${iconBtn('edit-investment','투자 후보 수정','edit',`data-id="${i.id}"`)}</div><h3>${esc(i.company)}${demo(i)}</h3><p class="row-sub">${esc(i.business)}</p><div class="card-money spaced">${won(i.desiredAmount)}<small>희망액</small></div><p class="row-sub">담당 · ${esc(i.contactName||'미정')}</p><div class="spaced">${safeLink(i.materialsUrl,'검토 자료 보기')}</div><div class="review-note">${esc(i.nextAction||'다음 할 일 미등록')}<br>${date(i.dueDate)} ${due(i.dueDate)}</div><p class="notice-small">${esc(i.note||'')}</p></article>`).join('')||'<div class="empty-col">등록된 후보가 없습니다</div>'}</section>`).join('')}</div><p class="notice-small">희망액은 후보가 요청한 금액 기록이며 가치평가·투자 승인·집행액이 아닙니다. 수요·공급·영업직원 검토 화면에는 이 데이터가 제공되지 않습니다</p>`}
function openInvestment(id){const i=(state.investments||[]).find(x=>x.id===id)||{mode:'introduction',status:'review',desiredAmount:0,isDemo:false};formDialog(id?'투자 후보 수정':'투자 후보 등록','거래 실행 없이 내부 검토 사항만 관리합니다',field('후보 회사명 *','company',i.company,'text','required maxlength="200"')+field('담당자','contactName',i.contactName,'text','maxlength="100"')+selectField('검토 방식','mode',{direct:'우리 회사 직접 투자 검토',introduction:'투자자 연결'},i.mode)+selectField('진행 상태','status',investmentStatuses,i.status)+field('희망 투자액 (원)','desiredAmount',i.desiredAmount,'number','min="0" step="1" required',true)+area('사업 내용','business',i.business)+field('자료 링크','materialsUrl',i.materialsUrl,'url','placeholder="https://"',true)+field('다음 할 일','nextAction',i.nextAction,'text','maxlength="500"')+field('다음 행동 기한','dueDate',i.dueDate,'date')+area('검토 메모 · 결정 근거','note',i.note)+`<label class="checkbox-field field wide"><input type="checkbox" name="isDemo" ${i.isDemo?'checked':''}>가상 투자 후보로 표시</label>`,d=>api(`investments${id?'/'+id:''}`,id?'PATCH':'POST',{...d,desiredAmount:Number(d.desiredAmount),isDemo:d.isDemo==='on'}),{extra:id?btn('delete-investment','삭제','danger','',`data-id="${id}"`):''})}
let crmOwner='';
function renderCRM(){const sp=state.salespeople||[],activities=state.activities||[];const ps=state.projects.filter(p=>!crmOwner||p.ownerId===crmOwner);return `${pageHead('SALES RELATIONSHIPS','영업 CRM','고객별 담당자와 상담 기록을 프로젝트 흐름에 연결합니다',btn('new-activity','상담활동 기록','primary','plus'))}<div class="toolbar"><div class="filters"><select id="crm-owner" class="filter" aria-label="영업담당자 필터"><option value="">모든 영업담당자</option>${options(Object.fromEntries(sp.map(s=>[s.id,s.name])),crmOwner)}</select></div>${operatorMode==='admin'?btn('new-salesperson','영업담당자 등록','small','plus'):''}</div><section class="panel spaced"><h2>영업자 추천 링크</h2>${sp.map(person=>`<p>${esc(person.name)} · ${esc(person.referralCode||'미설정')} ${person.referralCode?`<a href="/signup.html?ref=${encodeURIComponent(person.referralCode)}">이 추천코드로 가입</a>`:''}</p>`).join('')}</section><div class="table-wrap"><table><thead><tr><th>고객 / 담당자</th><th>영업담당자</th><th>의뢰 · 영업 단계</th><th>다음 행동</th><th>최근 상담</th><th>관리</th></tr></thead><tbody>${ps.map(p=>{const acts=activities.filter(a=>a.projectId===p.id).sort((a,b)=>b.activityDate.localeCompare(a.activityDate)),next=tasksFor(p.id).filter(t=>!t.done).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'))[0];return `<tr><td><a href="#projects/${p.id}">${esc(p.company)}</a>${demo(p)}<div class="row-sub">${esc(p.contactName||'담당자 미정')}</div></td><td>${esc(sp.find(s=>s.id===p.ownerId)?.name||'미배정')}<div class="row-sub">최초 추천: ${esc(p.referralCode||'없음')}</div>${p.consultationRef?`<div class="row-sub">접수: ${esc(p.consultationRef)}</div>`:''}</td><td>${badge(p.stage)}<div class="row-sub">${esc(p.name)}</div></td><td>${next?esc(next.title)+`<div class="row-sub">${date(next.dueDate)} ${due(next.dueDate)}</div>`:'미등록'}</td><td>${acts[0]?`${date(acts[0].activityDate)}<div class="row-sub">${esc(acts[0].content.slice(0,70))}</div>`:'상담 기록 없음'}</td><td>${iconBtn('new-activity','상담 기록 추가','plus',`data-project="${p.id}"`)}${iconBtn('edit-project','담당자 배정 / 프로젝트 수정','edit',`data-id="${p.id}"`)}</td></tr>`}).join('')}</tbody></table></div><section class="panel spaced"><div class="section-title"><h2>최근 상담활동</h2></div>${activities.filter(a=>ps.some(p=>p.id===a.projectId)).sort((a,b)=>b.activityDate.localeCompare(a.activityDate)).map(a=>`<div class="todo-item"><span class="avatar">${({call:'통화',meeting:'미팅',note:'메모'})[a.type]}</span><div class="todo-body"><div class="todo-name">${esc(a.content)}</div><div class="todo-sub"><a href="#projects/${a.projectId}">${esc(project(a.projectId)?.company||'')}</a> · ${date(a.activityDate)} · ${esc(sp.find(s=>s.id===a.salespersonId)?.name||'담당 미정')}</div></div><div>${iconBtn('edit-activity','상담활동 수정','edit',`data-id="${a.id}"`)}${iconBtn('delete-activity','상담활동 삭제','trash',`data-id="${a.id}"`)}</div></div>`).join('')||'<p class="notice-small">아직 상담활동 기록이 없습니다</p>'}</section><p class="notice-small">담당자 등록은 내부 CRM 명부입니다. 실제 직원 초대·회원 권한 부여가 실행되지 않습니다</p>`}
function openActivity(id,projectId){const a=(state.activities||[]).find(x=>x.id===id)||{projectId,type:'call',activityDate:today()};if(!state.projects.length)return toast('프로젝트를 먼저 등록해 주세요',true);formDialog(id?'상담활동 수정':'상담활동 기록','실제 확인한 상담 내용과 다음 행동을 남겨 주세요',selectField('프로젝트','projectId',Object.fromEntries(state.projects.map(p=>[p.id,`${p.company} · ${p.name}`])),a.projectId,true)+selectField('영업담당자','salespersonId',{'':'미지정',...Object.fromEntries((state.salespeople||[]).map(s=>[s.id,s.name]))},operatorMode==='sales'?operatorEntity:a.salespersonId||'')+selectField('활동 유형','type',{call:'통화',meeting:'미팅',note:'메모'},a.type)+field('활동일','activityDate',a.activityDate,'date','required',true)+area('상담 내용 *','content',a.content,true,'required'),d=>api(`activities${id?'/'+id:''}`,id?'PATCH':'POST',{...d,salespersonId:operatorMode==='sales'?operatorEntity:d.salespersonId||null}))}
function openSalesperson(){formDialog('영업담당자 등록','내부 명부용입니다. 직원 계정이 생성되지는 않습니다',field('이름 *','name','','text','required maxlength="100"',true)+field('추천코드 (비우면 자동 생성)','referralCode','','text','maxlength="100"',true)+area('메모','note',''),d=>api('salespeople','POST',{...d,isDemo:false}))}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||busy)return;const a=el.dataset.action,id=el.dataset.id;if(a==='program-view'){programView=el.dataset.value;render();return}const openers={'new-program':()=>openProgram(),'edit-program':()=>openProgram(id),'new-application':()=>openApplication(null,el.dataset.program),'edit-application':()=>openApplication(id),'new-investment':()=>openInvestment(),'edit-investment':()=>openInvestment(id),'new-activity':()=>openActivity(null,el.dataset.project),'edit-activity':()=>openActivity(id),'new-salesperson':()=>openSalesperson()};if(openers[a])return openers[a]();const types={program:['programs','지원사업'],application:['applications','신청 기록'],investment:['investments','투자 후보'],activity:['activities','상담활동']};const t=types[a.replace('delete-','')];if(a.startsWith('delete-')&&t)confirmDialog(`${t[1]}을 삭제할까요?`,'이 내부 기록이 삭제됩니다. 먼저 필요한 내용을 백업해 주세요.',()=>api(`${t[0]}/${id}`,'DELETE'),'삭제',true)});
app.addEventListener('change',async e=>{if(e.target.id==='operator-role'){if(busy){e.target.value=operatorMode==='admin'?'admin':'sales:'+operatorEntity;return}const value=e.target.value;operatorMode=value==='admin'?'admin':'sales';operatorEntity=value==='admin'?'':value.slice(6);crmOwner='';remember('ax-operator-mode',operatorMode);remember('ax-operator-entity',operatorEntity);state=null;app.innerHTML='<div role="status">선택한 역할을 불러오는 중…</div>';if(modal.open)modal.close();location.hash='dashboard';try{if(!await refresh())return;toast('검토용 역할을 전환했습니다. 실제 인증이 아닙니다')}catch(err){toast(err.message,true)}return}if(e.target.id==='crm-owner'){crmOwner=e.target.value;render()}});

document.addEventListener('click',async event=>{if(event.target.closest('[data-action="retry-refresh"]'))try{await refresh()}catch(error){toast(error.message,true)}});

document.addEventListener('click',event=>{const button=event.target.closest('[data-action="share-quote"]');if(!button||busy)return;const q=state.quotes.find(q=>q.id===button.dataset.id);if(q)confirmDialog(q.sharedWithBuyer?'고객 공유를 해제할까요?':'검토한 견적을 고객에게 공유할까요?','자유텍스트의 연락처와 내부 정보도 확인해 주세요. 편집 중인 미저장 내용은 공유에 포함되지 않습니다.',()=>api('quotes/'+q.id,'PATCH',{sharedWithBuyer:!q.sharedWithBuyer}))});
